r"""Datasets for copula examples, fetched rather than vendored.

**Why nothing is bundled.** R's ``copula`` package is GPL-3, and so are the
datasets inside it (``loss``, ``rdj``, ``gasoil``, ``uranium``, ``SMI.12``);
``lcopula::danube`` is GPL-3 and ``survival``'s are LGPL. Copying any of them
into an MIT package would be a licence conflict, however convenient. Numbers
*generated by running* GPL software are facts and are fine to commit -- which is
why the golden fixtures are in the repository and the datasets are not.

So this module ships **URLs, licences and SHA-256 digests**, and fetches on first
use. Every source here is public domain or permissively licensed, and the digest
is checked on arrival: a silently changed upstream file would otherwise turn a
reproducible example into an irreproducible one.

============================  ================================================
:func:`available`             What can be loaded, with licence and source.
:func:`load`                  Fetch (once), verify, cache and parse.
:func:`cache_dir`             Where the files live.
:func:`clear_cache`           Remove them.
============================  ================================================

Nothing here is imported at package load, and no network call happens until
:func:`load` is called.

Examples
--------
>>> from rcopula.datasets import available
>>> sorted(available())
['ghcn_temperature', 'nwis_peaks']
>>> available()["nwis_peaks"].licence
'public domain (work of the US Government)'
"""

from __future__ import annotations

import hashlib
import io
import os
from dataclasses import dataclass
from pathlib import Path
from typing import Any

import pandas as pd

__all__ = ["DatasetSpec", "available", "cache_dir", "clear_cache", "load"]

#: Read timeout for a fetch, in seconds. Short enough that a hung mirror fails
#: rather than stalling a test run.
_TIMEOUT = 60


@dataclass(frozen=True)
class DatasetSpec:
    """Where a dataset comes from, and what it is for.

    Attributes
    ----------
    name : str
        Key in :func:`available`.
    description : str
        One line on what the columns mean.
    url : str
        Where it is fetched from.
    licence : str
        Why it is legitimate to redistribute a *link* to it and cache it.
    sha256 : str or None
        Digest of the raw bytes, checked on every fetch. ``None`` means the
        upstream file is not byte-stable (a live query endpoint), in which case
        the shape is checked instead.
    reader : str
        Which parser to use.
    columns : tuple of str
        The columns the loader returns, in order.
    citation : str
        What to cite when a result depends on it.
    """

    name: str
    description: str
    url: str
    licence: str
    sha256: str | None
    reader: str
    columns: tuple[str, ...]
    citation: str


_REGISTRY: dict[str, DatasetSpec] = {
    "nwis_peaks": DatasetSpec(
        name="nwis_peaks",
        description=(
            "Annual peak streamflow and gauge height for a single USGS station. "
            "The canonical bivariate flood-frequency pair, and the setting the "
            "Kendall return period was invented for."
        ),
        url=(
            "https://nwis.waterdata.usgs.gov/nwis/peak?site_no=01646500&agency_cd=USGS&format=rdb"
        ),
        licence="public domain (work of the US Government)",
        sha256=None,  # a live query endpoint; grows by one row per year
        reader="usgs_rdb",
        columns=("water_year", "peak_flow", "gauge_height"),
        citation=(
            "U.S. Geological Survey, National Water Information System, "
            "station 01646500 (Potomac River near Washington, DC)."
        ),
    ),
    "ghcn_temperature": DatasetSpec(
        name="ghcn_temperature",
        description=(
            "Daily maximum and minimum temperature and precipitation from one "
            "GHCN-Daily station. Precipitation's atom at zero doubles as a "
            "discrete-margin and ties test case."
        ),
        url="https://www.ncei.noaa.gov/pub/data/ghcn/daily/by_station/USW00023174.csv.gz",
        licence="CC0 / public domain (NOAA GHCN-Daily)",
        sha256=None,  # updated daily upstream
        reader="ghcn_csv",
        columns=("date", "tmax", "tmin", "prcp"),
        citation=(
            "Menne, M. J. et al. (2012). An overview of the Global Historical "
            "Climatology Network-Daily database. J. Atmos. Oceanic Technol. "
            "29, 897-910. Station USW00023174 (Los Angeles International Airport)."
        ),
    ),
}


def available() -> dict[str, DatasetSpec]:
    """Every dataset that can be loaded, keyed by name.

    Examples
    --------
    >>> from rcopula.datasets import available
    >>> spec = available()["nwis_peaks"]
    >>> spec.columns
    ('water_year', 'peak_flow', 'gauge_height')
    >>> "public domain" in spec.licence
    True
    """
    return dict(_REGISTRY)


def cache_dir() -> Path:
    """Where fetched files are kept.

    Honours ``RCOPULA_DATA`` if set, otherwise ``XDG_CACHE_HOME``, otherwise
    ``~/.cache``.

    Examples
    --------
    >>> from rcopula.datasets import cache_dir
    >>> cache_dir().name
    'rcopula'
    """
    if override := os.environ.get("RCOPULA_DATA"):
        return Path(override)
    base = os.environ.get("XDG_CACHE_HOME") or (Path.home() / ".cache")
    return Path(base) / "rcopula"


def clear_cache() -> int:
    """Delete every cached file. Returns how many were removed."""
    directory = cache_dir()
    if not directory.exists():
        return 0
    removed = 0
    for path in directory.iterdir():
        if path.is_file():
            path.unlink()
            removed += 1
    return removed


def _digest(payload: bytes) -> str:
    return hashlib.sha256(payload).hexdigest()


def _verify(payload: bytes, spec: DatasetSpec) -> None:
    """Check the digest, when the source is byte-stable enough to have one.

    Split out from :func:`_fetch` so the check can be tested without a network
    call -- which is the only way to test it reliably at all.
    """
    if spec.sha256 is None:
        return
    actual = _digest(payload)
    if actual != spec.sha256:
        raise OSError(
            f"{spec.name}: the download does not match its recorded SHA-256.\n"
            f"  expected {spec.sha256}\n  got      {actual}\n"
            "The upstream file has changed, so a result computed from it would "
            "not reproduce. Report this rather than working around it."
        )


def _fetch(spec: DatasetSpec) -> bytes:
    """Download, then verify."""
    import urllib.request

    request = urllib.request.Request(
        spec.url, headers={"User-Agent": "rcopula (https://pypi.org/project/rcopula)"}
    )
    with urllib.request.urlopen(request, timeout=_TIMEOUT) as response:
        payload: bytes = response.read()
    _verify(payload, spec)
    return payload


def load(
    name: str,
    *,
    download: bool = True,
    refresh: bool = False,
    **kwargs: Any,
) -> pd.DataFrame:
    """Load a dataset, fetching and caching it on first use.

    Parameters
    ----------
    name : str
        A key from :func:`available`.
    download : bool
        If ``False``, use the cache only and raise rather than reach the
        network. Useful in tests and offline builds.
    refresh : bool
        Re-fetch even if a cached copy exists.

    Returns
    -------
    DataFrame
        With the columns named in the spec, rows containing missing values in
        those columns dropped, and the index reset.

    Raises
    ------
    KeyError
        If ``name`` is not in the registry -- listing what is.
    OSError
        If the download fails its digest check, or if it is needed and
        ``download=False``.

    Examples
    --------
    >>> import rcopula as rc
    >>> flood = rc.datasets.load("nwis_peaks")        # doctest: +SKIP
    >>> rc.cor_kendall(flood[["peak_flow", "gauge_height"]])   # doctest: +SKIP
    """
    if name not in _REGISTRY:
        raise KeyError(f"unknown dataset {name!r}; available: {sorted(_REGISTRY)}")
    spec = _REGISTRY[name]

    directory = cache_dir()
    directory.mkdir(parents=True, exist_ok=True)
    cached = directory / f"{name}.raw"

    if refresh or not cached.exists():
        if not download:
            raise OSError(
                f"{name} is not cached at {cached} and download=False. "
                "Call load(..., download=True) once with network access; the "
                "file is then reused."
            )
        cached.write_bytes(_fetch(spec))

    frame = _READERS[spec.reader](cached.read_bytes(), spec, **kwargs)
    frame = frame.dropna(subset=list(spec.columns)).reset_index(drop=True)
    frame.attrs["dataset"] = spec.name
    frame.attrs["licence"] = spec.licence
    frame.attrs["citation"] = spec.citation
    return frame


def _read_usgs_rdb(payload: bytes, spec: DatasetSpec, **_: Any) -> pd.DataFrame:
    """USGS RDB: comment lines start with ``#``, then a header, then a row of
    format specifiers that has to be skipped."""
    text = payload.decode("utf-8", errors="replace")
    lines = [line for line in text.splitlines() if not line.startswith("#")]
    if len(lines) < 3:
        raise OSError(f"{spec.name}: the download has no data rows")
    body = "\n".join([lines[0], *lines[2:]])
    raw = pd.read_csv(io.StringIO(body), sep="\t", dtype=str)

    dates = pd.to_datetime(raw["peak_dt"], errors="coerce")
    # A water year runs October to September, so October onward belongs to the
    # next one -- getting this wrong shifts every autumn flood by a year.
    year = dates.dt.year + (dates.dt.month >= 10).astype("Int64")
    return pd.DataFrame(
        {
            "water_year": year,
            "peak_flow": pd.to_numeric(raw["peak_va"], errors="coerce"),
            "gauge_height": pd.to_numeric(raw["gage_ht"], errors="coerce"),
        }
    )


def _read_ghcn_csv(payload: bytes, spec: DatasetSpec, **_: Any) -> pd.DataFrame:
    """GHCN-Daily per-station CSV: one row per element per day, in tenths."""
    import gzip

    text = gzip.decompress(payload).decode("utf-8", errors="replace")
    raw = pd.read_csv(
        io.StringIO(text),
        header=None,
        usecols=[0, 1, 2, 3],
        names=["station", "date", "element", "value"],
        dtype={"date": str},
    )
    wanted = raw[raw["element"].isin(["TMAX", "TMIN", "PRCP"])]
    wide = wanted.pivot_table(index="date", columns="element", values="value", aggfunc="first")
    for element in ("TMAX", "TMIN", "PRCP"):
        if element not in wide:
            raise OSError(f"{spec.name}: the download is missing {element}")
    return pd.DataFrame(
        {
            "date": pd.to_datetime(wide.index, format="%Y%m%d", errors="coerce"),
            "tmax": wide["TMAX"].to_numpy() / 10.0,  # tenths of degrees C
            "tmin": wide["TMIN"].to_numpy() / 10.0,
            "prcp": wide["PRCP"].to_numpy() / 10.0,  # tenths of mm
        }
    ).reset_index(drop=True)


_READERS = {"usgs_rdb": _read_usgs_rdb, "ghcn_csv": _read_ghcn_csv}
